  function requestStats(admin=false){const items=threads.filter(canSee);const rows=admin?[['activeIssues',items.filter(x=>x.kind==='issue'&&!['closed','resolved'].includes(x.status)).length,'file','overview'],['openChats',items.filter(x=>x.kind==='chat'&&x.status==='open').length,'chat','allConversations'],['needReply',items.filter(x=>x.unread).length,'chat','awaitingReply'],['unassignedStat',items.filter(x=>!x.assigned&&!['closed','resolved'].includes(x.status)).length,'people','teamView']]:[['activeIssues',items.filter(x=>x.kind==='issue'&&!['closed','resolved'].includes(x.status)).length,'file','requests'],['needReply',items.filter(x=>unreadCount(x)).length,'chat','unread'],['resolved',items.filter(x=>x.kind==='issue'&&x.status==='resolved').length,'check','issues'],['openChats',items.filter(x=>x.kind==='chat'&&x.status==='open').length,'chat','chat']];return `<div class="stats">${rows.map(([label,value,symbol,caption])=>`<div class="stat"><div class="flex">${T(label)}${icon(symbol)}</div><strong>${value.toLocaleString(state.lang==='bn'?'bn-BD':'en-US')}</strong><small>${T(caption)}</small></div>`).join('')}</div>`;}
